**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    ifstream plik("napisy.txt");
    string s;
    int freq[26] = {0};
    while (plik >> s) {
        for (char c : s) {
            freq[c - 'a']++;
        }
    }
    vector<pair<int, char>> histogram;
    for (int i = 0; i < 26; i++) {
        if (freq[i] > 0) {
            histogram.push_back({freq[i], (char)('a' + i)});
        }
    }
    sort(histogram.begin(), histogram.end(), [](const pair<int,char>& a, const pair<int,char>& b) {
        if (a.first != b.first) return a.first > b.first;
        return a.second < b.second;
    });
    for (auto& p : histogram) {
        cout << p.second << ": " << p.first << endl;
    }
    cout << "Roznych liter: " << histogram.size() << endl;
    return 0;
}
```

**Wyjasnienie**: Zliczamy czestotliwosci liter globalnie, budujemy wektor par i sortujemy go wedlug czestotliwosci malejaco, a przy rownej czestotliwosci — alfabetycznie rosnaco.

